TOUR_JS = "var TOUR_DECKS={\n fr9:{name:\"French 9\",nameAr:\"الفرنسية للصف التاسع\",code:\"FR · 09\",language:\"الفرنسي\",word:\"Leçon\",meaning:\"درس\"},\n en9:{name:\"English 9\",nameAr:\"الإنجليزية للصف التاسع\",code:\"EN · 09\",language:\"الإنجليزي\",word:\"Student\",meaning:\"طالب\"},\n enlit:{name:\"English Literature 12\",nameAr:\"الأدب الإنجليزي للصف الثاني عشر\",code:\"EN · LIT\",language:\"الإنجليزي\",word:\"Novel\",meaning:\"رواية\"},\n ensci:{name:\"English Science 12\",nameAr:\"العلوم باللغة الإنجليزية للصف الثاني عشر\",code:\"EN · SCI\",language:\"الإنجليزي\",word:\"Atom\",meaning:\"ذرة\"}\n};\nvar TOUR_DECK=TOUR_DECKS[\"__DECK__\"];\nvar ONBOARD_STEPS=[\n {icon:\"✦\",eyebrow:\"مرحباً بك في الاستوديو\",title:\"مساحتك لاختيار تصميم بطاقاتك\",text:\"أهلاً بك في معرض \"+TOUR_DECK.name+\"؛ استكشف التصاميم، افحص البطاقة من الوجهين، اضبط الصوت، ثم أنشئ رزمة Anki مرتّبة من مكان واحد.\",tip:\"هذه الجولة تعريفية فقط؛ لن تغيّر اختياراتك أو إعدادات الرزمة.\"},\n {icon:\"▦\",eyebrow:\"01 · استكشاف التصاميم\",title:\"كل القوالب أمامك بوضوح\",text:\"تصفّح القوالب المئة، واستخدم البحث والتصنيفات لتصل إلى الشكل الذي تريده. افتح المعاينة الكبيرة عندما تحتاج إلى رؤية التفاصيل قبل الاختيار.\",tip:\"اكتب جزءاً من اسم التصميم أو استخدم التصنيف لتقليل النتائج بسرعة.\"},\n {icon:\"◫\",eyebrow:\"02 · معاينة البطاقة\",title:\"افحص الوجهين قبل اعتماد التصميم\",text:\"افتح المعاينة المفردة، راجع وضوح الكلمة والمعنى والمسافات، ثم اقلب البطاقة لمراجعة الجهة الأخرى. انتقل بين التصاميم للمقارنة قبل اتخاذ القرار.\",tip:\"تأكد من أن النص واضح في الوجهين، وليس في الوجه الأمامي فقط.\"},\n {icon:\"✓\",eyebrow:\"03 · اختيار القوالب\",title:\"ابنِ مجموعة متناسقة\",text:\"حدّد القالب الذي يعجبك، أو اختر أكثر من قالب لتوزيع البطاقات عليها. ستبقى اختياراتك ظاهرة في منطقة التحديد لتراجعها قبل التصدير.\",tip:\"ابدأ بعدد قليل من القوالب المتناسقة، ثم وسّع المجموعة عندما تتأكد من النتيجة.\"},\n {icon:\"♫\",eyebrow:\"04 · إعداد الصوت\",title:\"اضبط النطق واستمع إلى العيّنة\",text:\"اختر صوت \"+TOUR_DECK.language+\" والصوت العربي من الخيارات المتاحة، واضبط السرعة والفواصل. استمع إلى المعاينة الصوتية قبل إنشاء الرزمة كاملة.\",tip:\"جرّب عيّنة قصيرة أولاً، ثم اعتمد الإعدادات التي تناسبك.\"},\n {icon:\"⇩\",eyebrow:\"05 · إنشاء الرزمة\",title:\"صدّر ملفاً جاهزاً للاستيراد\",text:\"راجع اسم الرزمة والقوالب وإعدادات الصوت، ثم ابدأ التصدير. سينشأ ملف بصيغة APKG يمكنك فتحه في تطبيق Anki لاستيراد البطاقات.\",tip:\"احتفظ بنسخة من ملف APKG بعد تنزيله، ثم افتحه في Anki وتأكد من ظهور البطاقات كما عاينتها.\"}\n];\nvar onbStep=0;\nvar onboardReturnFocus=null;\nvar onboardPreviousOverflow=\"\";\n\nfunction tourVisualForStep(index){\n var top='<div class=\"demo-window\"><div class=\"demo-top\"><span class=\"demo-dots\"><i></i><i></i><i></i></span><span class=\"demo-caption\">ANKI DESIGN STUDIO</span></div><div class=\"demo-body\">';\n if(index===0)return top+'<div class=\"demo-deck\"><b>'+TOUR_DECK.name+'</b><span class=\"demo-badge\">'+TOUR_DECK.code+'</span></div><div class=\"demo-metrics\"><div class=\"demo-metric\"><b>100</b><span>قالب للمعاينة</span></div><div class=\"demo-metric\"><b>01</b><span>معرض مستقل</span></div><div class=\"demo-metric\"><b>APKG</b><span>ملف التصدير</span></div></div><div style=\"margin-top:13px;padding:12px;border:1px solid rgba(167,139,250,.16);border-radius:11px;background:linear-gradient(100deg,rgba(124,58,237,.15),rgba(8,145,178,.08));color:#dbeafe;font-size:10px;text-align:center\">من اختيار التصميم إلى رزمة جاهزة ✦</div></div></div>';\n if(index===1)return top+'<div class=\"demo-search\">⌕ &nbsp; ابحث عن تصميم أو نمط... <b>100 قالب</b></div><div class=\"demo-template-grid\"><div class=\"demo-template\"><div class=\"demo-template-art\">▤</div><b>تصميم 08</b><small>بسيط وهادئ</small></div><div class=\"demo-template active\"><div class=\"demo-template-art\">✦</div><b>تصميم 24</b><small>محدد للمعاينة</small></div><div class=\"demo-template\"><div class=\"demo-template-art\">◈</div><b>تصميم 51</b><small>ألوان متوازنة</small></div></div><div style=\"display:flex;justify-content:space-between;margin-top:13px;color:#8191aa;font-size:9px\"><span>التصنيفات</span><span style=\"color:#c4b5fd\">استكشف ←</span></div></div></div>';\n if(index===2)return top+'<div class=\"demo-deck\"><b>معاينة البطاقة</b><span class=\"demo-badge\">FRONT / BACK</span></div><div class=\"demo-flashcard\"><div><div class=\"demo-word\">'+TOUR_DECK.word+'</div><div class=\"demo-meaning\">'+TOUR_DECK.meaning+'</div><small>مثال توضيحي من معرض '+TOUR_DECK.name+'</small></div></div><div class=\"demo-flip-row\"><span class=\"demo-mini-action\">السابق</span><span class=\"demo-mini-action\">قلب البطاقة ↻</span><span class=\"demo-mini-action\">التالي</span></div></div></div>';\n if(index===3)return top+'<div class=\"demo-deck\"><b>القوالب المحددة</b><span class=\"demo-badge\">YOUR SELECTION</span></div><div class=\"demo-selection-list\"><div class=\"demo-selected\"><i>✓</i> تصميم 24 <span>محدد</span></div><div class=\"demo-selected\"><i>✓</i> تصميم 51 <span>محدد</span></div><div class=\"demo-selected\"><i>＋</i> أضف تصميماً آخر <span>اختياري</span></div></div><div style=\"margin-top:12px;color:#8191aa;font-size:9px;text-align:center\">يمكنك مراجعة اختياراتك قبل المتابعة</div></div></div>';\n if(index===4){\n  var bars=[8,14,10,19,13,23,15,10,20,13,25,16,10,19,12,22,9,15,20,11,17,8,14,21,12];\n  var wave=bars.map(function(h){return '<i style=\"height:'+h+'px\"></i>';}).join(\"\");\n  var language=TOUR_DECK.code.indexOf(\"FR\")===0?\"FR\":\"EN\";\n  return top+'<div class=\"demo-deck\"><b>إعدادات الصوت</b><span class=\"demo-badge\">AUDIO STUDIO</span></div><div class=\"demo-voice-list\"><div class=\"demo-voice\"><div class=\"demo-voice-head\"><span>الصوت '+TOUR_DECK.language+'</span><span>'+language+'</span></div><div class=\"demo-wave\">'+wave+'</div></div><div class=\"demo-voice\"><div class=\"demo-voice-head\"><span>الصوت العربي</span><span>AR</span></div><div class=\"demo-wave\">'+wave+'</div></div></div><div style=\"display:flex;justify-content:space-between;margin-top:12px;color:#8191aa;font-size:9px\"><span>السرعة</span><b style=\"color:#67e8f9\">1.0×</b></div></div></div>';\n }\n return top+'<div class=\"demo-export\"><div class=\"demo-export-icon\">✓</div><b>الرزمة جاهزة للتصدير</b><small>'+TOUR_DECK.name+' · .APKG</small><div class=\"demo-checks\"><span>✓ القوالب المحددة</span><span>✓ بيانات البطاقات</span><span>✓ إعدادات الصوت</span><span>✓ ملف للاستيراد</span></div></div></div></div>';\n}\n\nfunction showOnboarding(){\n var overlay=document.getElementById(\"onboardOverlay\");\n if(!overlay||overlay.open)return;\n onboardReturnFocus=document.activeElement;\n onboardPreviousOverflow=document.body.style.overflow||\"\";\n onbStep=0;\n renderOnboardStep();\n try{if(typeof overlay.showModal===\"function\")overlay.showModal();else overlay.setAttribute(\"open\",\"\");}\n catch(_e){overlay.setAttribute(\"open\",\"\");}\n document.body.style.overflow=\"hidden\";\n window.setTimeout(function(){var box=document.getElementById(\"onboardBox\");var target=box&&box.querySelector(\"[data-tour-next]\");if(target)target.focus();},30);\n}\n\nfunction closeOnboarding(){\n var overlay=document.getElementById(\"onboardOverlay\");\n if(!overlay)return;\n try{if(typeof overlay.close===\"function\"&&overlay.open)overlay.close();else overlay.removeAttribute(\"open\");}\n catch(_e){overlay.removeAttribute(\"open\");}\n document.body.style.overflow=onboardPreviousOverflow;\n try{localStorage.setItem(\"anki___DECK___onboarded\",\"1\");}catch(_e){}\n var previous=onboardReturnFocus;\n onboardReturnFocus=null;\n if(previous&&typeof previous.focus===\"function\"&&document.contains(previous)){try{previous.focus({preventScroll:true});}catch(_e){try{previous.focus();}catch(_e2){}}}\n}\n\nfunction moveOnboardStep(delta){\n var next=onbStep+delta;\n if(next<0)return;\n if(next>=ONBOARD_STEPS.length){closeOnboarding();return;}\n onbStep=next;\n renderOnboardStep();\n window.setTimeout(function(){var box=document.getElementById(\"onboardBox\");var target=(box&&box.querySelector(\"[data-tour-next]\"))||(box&&box.querySelector(\"[data-tour-prev]\"));if(target)target.focus();},0);\n}\n\nfunction renderOnboardStep(){\n var box=document.getElementById(\"onboardBox\");\n if(!box)return;\n var step=ONBOARD_STEPS[onbStep];\n if(!step)return;\n var total=ONBOARD_STEPS.length;\n var percent=Math.round(((onbStep+1)/total)*100);\n var labels=[\"البداية\",\"استكشاف\",\"المعاينة\",\"الاختيار\",\"الصوت\",\"التصدير\"];\n var route=ONBOARD_STEPS.map(function(item,index){\n  var state=index===onbStep?\" active\":index<onbStep?\" done\":\"\";\n  return '<button type=\"button\" class=\"tour-route-item'+state+'\" onclick=\"onbStep='+index+';renderOnboardStep()\" '+(index===onbStep?'aria-current=\"step\"':'')+' aria-label=\"الانتقال إلى '+labels[index]+'\"><span class=\"tour-route-num\">'+(index<onbStep?\"✓\":String(index+1).padStart(2,\"0\"))+'</span><span class=\"tour-route-text\">'+labels[index]+'</span></button>';\n }).join(\"\");\n var h='<div class=\"tour-shell\"><aside class=\"tour-sidebar\"><div class=\"tour-brand\"><span class=\"tour-brand-mark\">A</span><div class=\"tour-brand-copy\"><b>ANKI DESIGN STUDIO</b><span>دليل الاستخدام السريع</span></div></div>';\n h+='<div class=\"tour-deck-chip\"><span>المعرض الحالي</span><strong>'+TOUR_DECK.name+'</strong></div><div><p class=\"tour-sidebar-heading\">رحلتك داخل المعرض</p><nav class=\"tour-route-list\" aria-label=\"مراحل الجولة\">'+route+'</nav></div>';\n h+='<div class=\"tour-sidebar-foot\">ست خطوات قصيرة للتعرّف على الأدوات الأساسية.<br><strong>'+TOUR_DECK.nameAr+'</strong></div></aside>';\n h+='<main class=\"tour-main\"><div class=\"tour-topline\"><div class=\"tour-step-counter\"><b>STEP '+String(onbStep+1).padStart(2,\"0\")+'</b><span>من '+String(total).padStart(2,\"0\")+'</span></div><button class=\"tour-close\" type=\"button\" onclick=\"closeOnboarding()\" aria-label=\"إغلاق الجولة\">×</button></div>';\n h+='<div class=\"tour-progress-wrap\"><div class=\"tour-progress-track\" role=\"progressbar\" aria-label=\"تقدم الجولة\" aria-valuemin=\"0\" aria-valuemax=\"100\" aria-valuenow=\"'+percent+'\"><div class=\"tour-progress-fill\" style=\"width:'+percent+'%\"></div></div><span class=\"tour-progress-copy\">'+percent+'٪</span></div>';\n h+='<section class=\"tour-content\" aria-live=\"polite\"><div class=\"tour-copy\"><div class=\"tour-icon\" aria-hidden=\"true\">'+step.icon+'</div><p class=\"tour-eyebrow\">'+step.eyebrow+'</p><h2 class=\"tour-title\" id=\"onboardStepTitle\">'+step.title+'</h2><p class=\"tour-text\">'+step.text+'</p><div class=\"tour-tip\"><span class=\"tour-tip-mark\" aria-hidden=\"true\">✦</span><div><b>معلومة مفيدة</b><span>'+step.tip+'</span></div></div></div>';\n h+='<div class=\"tour-visual\" aria-hidden=\"true\">'+tourVisualForStep(onbStep)+'</div></section>';\n h+='<footer class=\"tour-footer\"><span class=\"tour-footer-note\">'+TOUR_DECK.nameAr+' · الخطوة '+(onbStep+1)+' من '+total+'</span><div class=\"tour-actions\"><button class=\"tour-btn text\" type=\"button\" onclick=\"closeOnboarding()\">تخطي الجولة</button>';\n if(onbStep>0)h+='<button class=\"tour-btn\" data-tour-prev type=\"button\" onclick=\"moveOnboardStep(-1)\">السابق</button>';\n if(onbStep<total-1)h+='<button class=\"tour-btn primary\" data-tour-next type=\"button\" onclick=\"moveOnboardStep(1)\">'+(onbStep===0?\"ابدأ الجولة\":\"التالي\")+' ←</button>';\n else h+='<button class=\"tour-btn primary\" data-tour-next type=\"button\" onclick=\"closeOnboarding()\">إنهاء الجولة وابدأ ←</button>';\n h+='</div></footer></main></div>';\n box.innerHTML=h;\n box.setAttribute(\"aria-labelledby\",\"onboardStepTitle\");\n}\n\n(function bindPremiumTour(){\n var overlay=document.getElementById(\"onboardOverlay\");\n if(!overlay||overlay.dataset.premiumTourBound)return;\n overlay.dataset.premiumTourBound=\"1\";\n overlay.addEventListener(\"click\",function(event){if(event.target===overlay)closeOnboarding();});\n overlay.addEventListener(\"cancel\",function(event){event.preventDefault();closeOnboarding();});\n document.addEventListener(\"keydown\",function(event){\n  var active=document.getElementById(\"onboardOverlay\");\n  if(!active||!active.hasAttribute(\"open\"))return;\n  if(event.key===\"Escape\"){event.preventDefault();closeOnboarding();return;}\n  if(event.key===\"Tab\"){\n   var focusable=Array.prototype.slice.call(active.querySelectorAll(\"button:not([disabled]),a[href],input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex='-1'])\")).filter(function(el){return !!(el.offsetWidth||el.offsetHeight||el.getClientRects().length);});\n   if(!focusable.length){event.preventDefault();return;}\n   var first=focusable[0],last=focusable[focusable.length-1];\n   if(event.shiftKey&&(document.activeElement===first||document.activeElement===active)){event.preventDefault();last.focus();}\n   else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}\n   return;\n  }\n  var target=event.target;\n  var typing=target&&(target.tagName===\"INPUT\"||target.tagName===\"TEXTAREA\"||target.tagName===\"SELECT\"||target.isContentEditable);\n  if(typing||event.altKey||event.ctrlKey||event.metaKey)return;\n  if(event.key===\"ArrowLeft\"){event.preventDefault();moveOnboardStep(1);}\n  else if(event.key===\"ArrowRight\"){event.preventDefault();moveOnboardStep(-1);}\n });\n})();"
